 for(const c of supports(f)){const key=supportKey(c);if(seen.has(key)||!view.contains(C.latlng(c))||S.project.area&&!G.inside(c,ohlBounds()))continue;seen.add(key);if(count++>=1800)break;const info=meta[key]||{},confirmed=types[key],kind=confirmed||info.mappedKind||'unknown',marker=L.marker(C.latlng(c),{icon:supportIcon(kind,!confirmed&&!!info.mappedKind),zIndexOffset:400}).addTo(S.ohlSupportGroup);const typeLabel=kind==='pylon'||kind==='tower'?'Tower / pylon':kind==='portal'?'Portal':kind==='terminal'?'OHL terminal':kind==='pole'?'Pole':'Unidentified support',label=[typeLabel,info.ref,voltageLabel(info.voltage||m.voltage)].filter(Boolean).join(' · ');marker.bindTooltip(esc(label+(confirmed?'':' · mapped reference')),{permanent:S.map.getZoom()>=18&&kind!=='unknown',direction:'right',className:'map-label ohl-label',offset:[10,0]});marker.on('click',e=>{L.DomEvent.stopPropagation(e.originalEvent);C.chooseOhlSupport(f.id,key);});}
