function repeatedAssets(points,a,area){const result=[],groupId=C.uid(),pr=G.projection(points[0]);const ring=points.map(pr.xy),angle=ring.length>1?Math.atan2(ring[1][0]-ring[0][0],ring[1][1]-ring[0][1])*180/Math.PI:0;
 const add=(center,heading)=>{if(result.length>=2000)throw Error('Use a smaller area or more spacing; the limit is 2,000 objects per placement.');result.push(C.feature(a.imageData?'logo':'asset',G.rectangle(center,+a.length,+a.width,heading),{...a,groupId,angle:heading,centerLng:center[0],centerLat:center[1]}));};
 if(area){const theta=angle*Math.PI/180,u=[Math.sin(theta),Math.cos(theta)],v=[Math.cos(theta),-Math.sin(theta)],local=ring.map(p=>[p[0]*u[0]+p[1]*u[1],p[0]*v[0]+p[1]*v[1]]),xs=local.map(p=>p[0]),ys=local.map(p=>p[1]),l=+a.length,w=+a.width,gap=+a.gap||0;for(let x=Math.min(...xs)+l/2;x<=Math.max(...xs)-l/2+.001;x+=l+gap){for(let y=Math.min(...ys)+w/2;y<=Math.max(...ys)-w/2+.001;y+=w+gap){if([[-l/2,-w/2],[l/2,-w/2],[l/2,w/2],[-l/2,w/2]].every(([dx,dy])=>ringContains([x+dx,y+dy],local)))add(pr.ll([x*u[0]+y*v[0],x*u[1]+y*v[1]]),angle);}}}
 else{const total=G.length(points),step=+a.length+(+a.gap||0);for(let d=+a.length/2;d<=total+.001;d+=step){let rem=d;for(let i=1;i<points.length;i++){const len=G.distance(points[i-1],points[i]);if(rem<=len){const a0=pr.xy(points[i-1]),b=pr.xy(points[i]),t=rem/len;add(pr.ll([a0[0]+t*(b[0]-a0[0]),a0[1]+t*(b[1]-a0[1])]),Math.atan2(b[0]-a0[0],b[1]-a0[1])*180/Math.PI);break;}rem-=len;}}}
 if(!result.length)throw Error('The drawn space is too small for this asset.');return result;
}
function finishDraw(){const t=S.tool,pts=copy(S.points),a=copy(S.options);if(t==='panelAreaPoints'){if(pts.length>=3)C.addPanelFill(pts,a);return;}if(['assetLine','assetArea','assetFreeLine','assetFreeArea'].includes(t)){if(pts.length<(/Area/.test(t)?3:2))return;try{const fs=repeatedAssets(pts,a,/Area/.test(t));S.project.features.push(...fs);C.cancelDraw();S.selected=fs[0].id;C.commit();C.toast(fs.length+' objects placed as a group.');}catch(e){C.toast(e.message);}return;}O.finishDraw();}
