function placeAssetAtScreen(k,x,y){const hit=document.elementFromPoint(x,y);if(hit?.closest('#studioDock,.floating-panel,#creatorWorkspace,.topbar,.modebar'))return false;const box=$('#mapViewport')?.getBoundingClientRect()||$('#map').getBoundingClientRect();if(x<box.left||x>box.right||y<box.top||y>box.bottom)return false;ui.asset=k;const a=readSelected();if(a.surface)return false;const c=C.coord(S.map.mouseEventToLatLng({clientX:x,clientY:y}));if(S.mode==='plan'&&S.project.area&&!C.insidePlanFrame(c)){C.toast('Drop inside the site drawing.');return false;}const f=C.feature(a.type==='panel'?'panel':a.imageData?'logo':'asset',G.rectangle(c,+a.length,+a.width,0),{...a,centerLng:c[0],centerLat:c[1],angle:0});S.project.features.push(f);S.selected=f.id;C.commit();C.toast(a.name+' placed.');return true;}
