function layersHTML(){const seen=new Set(),fs=S.project.features.filter(f=>!f.properties.guideHidden).slice().reverse(),rows=[];for(const f of fs){const gid=f.properties.groupId||f.id;if(seen.has(gid))continue;seen.add(gid);const members=C.groupMembers(f);rows.push(`<div class="layer-object"><button class="layer-name" data-action="select:${esc(f.id)}">${esc(f.properties.label||f.properties.type)}<small>${members.length>1?members.filter(x=>!x.properties.guideHidden).length+' objects · group':TYPES[f.properties.type]||f.properties.type}</small></button><button data-action="hideItem:${f.id}" title="${f.properties.hidden?'Show':'Hide'} object">${f.properties.hidden?'○':'◉'}</button><button data-action="lockItem:${f.id}" title="${f.properties.locked?'Unlock':'Lock'} object">${f.properties.locked?'◆':'◇'}</button><button data-action="raiseItem:${f.id}" title="Bring forward">↑</button><button data-action="lowerItem:${f.id}" title="Send backward">↓</button></div>`);}return '<p class="subtle">Top items draw above lower items. Group, hide or lock objects without removing them.</p>'+rows.join('')+'<details class="advanced-settings"><summary>Layer visibility</summary>'+O.layersHTML()+'</details>'+B('Materials schedule','open:schedule');}
