function brandingHTML(){return '<p class="subtle">Your designer details and enabled logos appear on new PDF exports. Empty fields are omitted.</p>'+F('designerName','Designer name',S.project.meta.creator||'')+F('designerCompany','Designer company',S.project.meta.designerCompany||'')+F('designerEmail','Designer email',S.project.meta.designerEmail||'')+F('designerPhone','Designer phone',S.project.meta.designerPhone||'')+B('Add company logo','uploadLogo',true)+(S.project.logos||[]).map(l=>`<div class="logo-row"><img src="${esc(l.data)}" alt="${esc(l.name)}"><div>${esc(l.name)}${C.checkedRow('Use in PDF','data-logo-export="'+esc(l.id)+'"',l.export!==false)}</div><button data-action="pickLogo:${esc(l.id)}">Place</button><button title="Remove logo from project" data-action="removeLogo:${esc(l.id)}">×</button></div>`).join('')+'<p class="subtle">PNG and JPEG · up to 8 logos. SAMI automatically fits the image to its aspect ratio for plan placement and export; you can still resize a placed logo afterwards.</p>';}
async function uploadLogo(file){if(!file)return;try{if(S.project.logos.length>=8)throw Error('This project already has 8 logos.');if(!/image\/(png|jpeg|webp)/.test(file.type))throw Error('Choose a PNG, JPEG or WebP image.');if(file.size>10*1024*1024)throw Error('Use a logo under 10 MB.');const url=URL.createObjectURL(file),im=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=url;});URL.revokeObjectURL(url);const scale=Math.min(1,640/Math.max(im.width,im.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/png');if(data.length>1000000)throw Error('Use a simpler or smaller logo image.');const ratio=im.width/im.height,max=4,length=ratio>=1?max:max*ratio,width=ratio>=1?max/ratio:max;S.project.logos.push({id:C.uid(),name:file.name.replace(/\.[^.]+$/,''),data,ratio,export:true,length,width});C.commit();C.openDrawer('branding');}catch(e){C.toast(e.message||'This logo could not be read.');}}
function accessPoints(){return S.project.features.filter(f=>f.properties.type==='accessPoint');}
function accessHTML(){return '<p class="subtle">Place entrances at the exact gate location. Give each an address or use its coordinates, then select it as your route destination.</p>'+B('Place access point','accessPoint',true)+accessPoints().map(f=>`<div class="item-row"><div><strong>${esc(f.properties.label)}</strong><small>${esc(f.properties.address||C.coordLabel(f.geometry.coordinates))}</small></div><button data-action="accessEdit:${f.id}">Edit</button><button data-action="accessRoute:${f.id}">Route here</button></div>`).join('');}
async function accessLookup(p){const out={address:'',what3words:''};try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${p[1]}&lon=${p[0]}&zoom=18`,{signal:AbortSignal.timeout(10000)}),d=await C.boundedJSON(r,200000);out.address=d.display_name||''}catch{}const key=String(C.readPref('sami.w3w.key')||window.SAMI_CONFIG?.what3wordsApiKey||'').trim();if(key)try{const r=await fetch(`https://api.what3words.com/v3/convert-to-3wa?coordinates=${encodeURIComponent(p[1]+','+p[0])}&key=${encodeURIComponent(key)}`,{signal:AbortSignal.timeout(10000)}),d=await C.boundedJSON(r,200000);if(d.words)out.what3words='///'+d.words}catch{}return out}
function editAccessPoint(f,c){const m=f?.properties||{},p=c||f.geometry.coordinates,isNew=!f;C.showModal('Access point',F('gateName','Entrance name',m.label||'Site entrance')+F('gateAddress','Address / postcode',m.address||'')+F('gateW3w','what3words',m.what3words||'')+F('gateNotes','Arrival instructions',m.arrivalInstructions||'')+C.checkedRow('Use this entrance for project address','id="gateProjectAddress"',m.projectEntrance!==false)+'<p class="subtle">'+esc(C.coordLabel(p))+(String(C.readPref('sami.w3w.key')||window.SAMI_CONFIG?.what3wordsApiKey||'').trim()?' · address and what3words auto-fill from the pin':' · mapped address auto-fills; add a what3words API key in Settings for automatic 3-word addresses')+'</p>'+B('Refresh location details','gateGeocode')+B('Save access point','gateSave',true));const fill=async(silent=false)=>{const d=await accessLookup(p);if($('#gateAddress')&&d.address)$('#gateAddress').value=d.address;if($('#gateW3w')&&d.what3words)$('#gateW3w').value=d.what3words;if(!silent&&!d.address&&!d.what3words)C.toast('No automatic location details were available. Coordinates are retained.')};if(isNew)fill(true);$('#modalBody').onclick=async e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='gateGeocode')await fill();if(action==='gateSave'){const props={...m,label:$('#gateName').value.trim()||'Site entrance',address:$('#gateAddress').value.trim(),what3words:$('#gateW3w').value.trim(),arrivalInstructions:$('#gateNotes').value.trim(),projectEntrance:$('#gateProjectAddress').checked,includeLegend:true};if(f)f.properties={...f.properties,...props};else{f=C.feature('accessPoint',{type:'Point',coordinates:p},props);S.project.features.push(f);}if(props.projectEntrance){if(props.address)S.project.meta.siteAddress=props.address;if(props.what3words)S.project.meta.what3words=props.what3words;S.project.meta.siteEntrance=props.label;S.project.meta.arrivalInstructions=props.arrivalInstructions}C.closeModal();S.selected=f.id;C.commit();C.openDrawer('access');}};}
function routeToSiteHTML(){const pts=accessPoints();return (pts.length?C.choice('routeAccessPoint','Destination access point',{'':'Choose an entrance…',...Object.fromEntries(pts.map(f=>[f.id,f.properties.label]))},S.project.hgv.accessPointId||''):'')+B('Manage access points','open:access')+O.routeToSiteHTML();}
