function voiceHTML(){const profile=window.SAMI_CONFIG?.voiceProfile||{},endpoint=C.readPref('sami.naturalVoice.url')||window.SAMI_CONFIG?.voiceEndpoint||'',pack=window.SAMI_CONFIG?.recordedSpeechPack||{},live=C.readPref('sami.voice.liveFallback')==='on';return C.checkedRow('Spoken responses','id="voiceOutput"',C.readPref('sami.voice.output')!=='off')+'<div class="card voice-profile-card"><strong>'+esc(profile.displayName||'SAMI Voice')+'</strong><p class="subtle">Brand pronunciation: <b>SAMI → Sammy</b>. Detailed answers remain on screen; the voice speaks a concise matching meaning from the recorded speech pack. Robotic device TTS stays disabled.</p><div class="voice-profile-meta"><span>Profile '+esc(profile.id||'sami-voice-v1')+'</span><span>'+Object.keys(pack).length+' bundled speech clips</span></div></div><div class="row equal">'+B('Play recorded voice','testVoice')+B('Test speech pack','testSpeechPack')+'</div>'+C.checkedRow('Use HTTPS live fallback for uncovered replies','id="voiceLiveFallback"',live)+F('naturalVoiceUrl','Optional HTTPS voice endpoint',endpoint,'url','placeholder="https://your-project.supabase.co/functions/v1/sami-voice"')+'<p class="subtle">Normal operation is uses bundled recordings offline. If an answer is not covered, SAMI uses the generic recorded response unless live fallback is explicitly enabled. Voice audio: AI Doc Maker.</p>'+F('connectedAiUrl','AI asset design endpoint',C.readPref('sami.ai.url')||window.SAMI_CONFIG?.aiEndpoint||'','url','placeholder="https://your-service/assist"')+B('Save connections','saveConnections',true);}
function initVoice(){C.setPref('sami.voice.output',C.readPref('sami.voice.output')||'on');C.setPref('sami.voice.liveFallback',C.readPref('sami.voice.liveFallback')||'off');try{window.speechSynthesis?.cancel();}catch{}C.updateVoiceButton();}
function stopAudio(){voiceSeq++;voiceController?.abort();voiceController=null;if(voiceAudio){voiceAudio.pause();if(voiceAudio.src?.startsWith('blob:'))URL.revokeObjectURL(voiceAudio.src);voiceAudio=null;}}
function spokenText(text){return String(text||'').replace(/\bS\s*\.\s*A\s*\.\s*M\s*\.\s*I\.?/gi,'Sammy').replace(/\bS\s+A\s+M\s+I\b/gi,'Sammy').replace(/\bSAMI\b/gi,'Sammy').replace(/https?:\/\/\S+/gi,m=>'web link'+((m.match(/[.,!?;:)]+$/)||[''])[0])).replace(/\s+/g,' ').trim();}
function semanticVoiceId(text){const t=spokenText(text).toLowerCase();if(!t)return'';
 if(/(official|government|guidance|source).*(link|screen)|linked.*official source/.test(t))return'officialSource';
 if(/(connected service|service).*(didn't|did not|failed|unavailable|not respond)|local drawing tools still work/.test(t))return'offline';
 if(/(define|set|draw).*(site area|site boundary).*(first|before)|site area.*(first|required|needed)/.test(t))return'needSiteArea';
 if(/(couldn't|could not|can't|cannot|failed|error|unavailable|isn't available|not available)/.test(t))return'error';
 if(/\b(pdf|export)\b.*\b(created|ready|generated|saved|complete|completed)\b|\b(created|generated)\b.*\bpdf\b/.test(t))return'pdf';
 if(/\b(route|route to site|journey)\b.*\b(ready|planned|created|complete|completed|generated)\b|\bplanned\b.*\broute\b/.test(t))return'route';
 if(/\b(overhead line|overhead power|ohl)\b/.test(t))return'ohl';
 if(/\b(service|services|utilities|utility)\b.*\b(refresh|refreshed|mapped|updated|found|loaded|snapshot)\b/.test(t))return'services';
 if(/\b(map|satellite|cad|base)\b.*\b(view|switched|changed|mode)\b|\bswitched\b.*\b(map|satellite|cad)\b/.test(t))return'mapView';
 if(/\b(access point|entrance|gate)\b/.test(t)&&/\b(add|added|create|created|place|placed|save|saved|ready)\b/.test(t))return'accessPoint';
 if(/\b(site area|site boundary|boundary)\b.*\b(defined|created|set|drawn|ready)\b|\bdefined\b.*\bsite\b/.test(t))return'siteArea';
 if(/\b(panel run|trakway run|trackway run)\b/.test(t))return'panelRun';
 if(/\b(saved|save complete|changes are saved)\b/.test(t))return'saved';
 if(/\bundo|undone|reverted\b/.test(t))return'undo';
 if(/\b(create|created|build|built|make|made|generate|generated|materialise|materialize|produced)\b/.test(t))return'created';
 if(/\b(add|added|insert|inserted|place|placed)\b/.test(t))return'added';
 if(/\b(update|updated|change|changed|edit|edited|move|moved|position|positioned|group|grouped|ungroup|duplicate|duplicated|delete|deleted|rotate|rotated|resize|resized|colour|color)\b/.test(t))return'updated';return'';}
function recordedVoiceFor(text,mode='auto'){const cfg=window.SAMI_CONFIG||{},normal=spokenText(text).toLowerCase();if(mode==='recorded'||/^(hello[, ]+i['’]?m sammy\b|sammy is ready\.?$)/i.test(normal))return cfg.recordedVoiceWelcome||'';if(normal==='you can read my response on screen.')return cfg.recordedVoiceResponse||'';const id=semanticVoiceId(text);return id?cfg.recordedSpeechPack?.[id]?.url||'':'';}
async function voiceCacheKey(text){if(!window.crypto?.subtle)return null;const profile=window.SAMI_CONFIG?.voiceProfile?.id||'sami-voice-v1',bytes=new TextEncoder().encode(profile+'|'+text),hash=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,'0')).join('');}
async function cachedVoice(text){try{if(!('caches'in window))return null;const key=await voiceCacheKey(text);if(!key)return null;const cache=await caches.open('sami-natural-voice-v1'),req=new Request(new URL('./__sami_voice__/'+key,location.href));const hit=await cache.match(req);return hit?await hit.blob():null;}catch{return null;}}
async function cacheVoice(text,blob){try{if(!('caches'in window))return;const key=await voiceCacheKey(text);if(!key)return;const cache=await caches.open('sami-natural-voice-v1'),req=new Request(new URL('./__sami_voice__/'+key,location.href));await cache.put(req,new Response(blob,{headers:{'Content-Type':blob.type||'audio/mpeg','X-SAMI-Voice-Profile':window.SAMI_CONFIG?.voiceProfile?.id||'sami-voice-v1'}}));}catch{}}
async function fetchNaturalVoice(text,url){const max=Math.max(200,Math.min(5000,+window.SAMI_CONFIG?.voiceProfile?.maxChars||4500)),speech=spokenText(text).slice(0,max),cached=await cachedVoice(speech);if(cached)return cached;voiceController=new AbortController();const timer=setTimeout(()=>voiceController?.abort(),20000);let r;try{r=await fetch(url,{method:'POST',mode:'cors',credentials:'omit',headers:{'Content-Type':'application/json','Accept':'audio/mpeg,audio/*'},body:JSON.stringify({text:speech,voice_profile:window.SAMI_CONFIG?.voiceProfile?.id||'sami-voice-v1',language:window.SAMI_CONFIG?.voiceProfile?.language||'en-GB',pronunciation:{SAMI:'Sammy'}}),signal:voiceController.signal});}finally{clearTimeout(timer);}if(!r.ok){let message='Voice service returned '+r.status+'.';try{const data=await r.clone().json();if(data?.error)message=String(data.error).slice(0,180);}catch{}throw Error(message);}if(!r.headers.get('content-type')?.startsWith('audio/'))throw Error('Speech service must return an audio response.');const blob=await r.blob();if(!blob.size||blob.size>12*1024*1024)throw Error('Speech response size is invalid.');await cacheVoice(speech,blob);return blob;}
async function speakOptional(text,options=false){const opt=typeof options==='object'&&options?options:{mode:options===true?'recorded':'auto'},force=!!opt.force||options===true;if(!force&&C.readPref('sami.voice.output')==='off')return;stopAudio();const seq=voiceSeq,url=C.readPref('sami.naturalVoice.url')||window.SAMI_CONFIG?.voiceEndpoint||'',mode=opt.mode||'auto',live=C.readPref('sami.voice.liveFallback')==='on';try{let src,blob,clip=mode==='service'?'':recordedVoiceFor(text,mode);if(clip){src=clip;}else if(url&&(mode==='service'||live)){blob=await fetchNaturalVoice(text,url);src=URL.createObjectURL(blob);}else{if(mode==='service')throw Error('Add an HTTPS voice endpoint first.');if(!force&&Date.now()-ui.lastVoice<3000)return;src=window.SAMI_CONFIG?.recordedVoiceResponse||'';if(!src)return;}if(seq!==voiceSeq)return;voiceAudio=new Audio(src);ui.lastVoice=Date.now();await voiceAudio.play();}catch(e){if(seq===voiceSeq&&e.name!=='AbortError')C.toast((e.message||'Natural speech unavailable.')+' The full answer is on screen.');}}
function helpHTML(){return '<div class="card"><strong>Designed for iPad, touch and keyboard</strong><p class="subtle">Pinch the canvas to zoom the map. Menus remain the same size. With freehand active, draw with one finger or Pencil; use two fingers to navigate. Long-press an asset tile, then drag it onto the canvas. Tap it for place mode.</p></div><table class="shortcut-table"><tr><th>Shortcut</th><th>Action</th></tr>'+[['V','Select / stop drawing'],['Space (hold)','Pan canvas'],['L / A','Point line / point area'],['F / Shift F','Freehand line / area'],['P','Place selected asset'],['M','Measure'],['S','Toggle snapping'],['Enter','Finish drawing'],['Escape','Cancel / close'],['⌘ / Ctrl Z','Undo'],['⌘ / Ctrl Shift Z','Redo'],['⌘ / Ctrl D','Duplicate selection'],['G / Shift G','Group / ungroup'],['Arrow keys','Move selected 0.1 m'],['Shift + arrows','Move selected 1 m'],['Delete','Delete selection'],['⌘ / Ctrl S','Save'],['⌘ / Ctrl E','Export'],['?','Help']].map(([a,b])=>'<tr><td><kbd>'+a+'</kbd></td><td>'+b+'</td></tr>').join('')+'</table>'+C.section('Quick guide')+'<p class="subtle">1. Find your site and define its boundary.<br>2. Pick an asset, then draw with the shared tools.<br>3. Select items to move, rotate, colour, group or lock.<br>4. Add entrances, designer details and logos.<br>5. Export the chosen site and route sheets.</p>'+B('Voice & AI connections','open:voice')+B('Materials schedule','open:schedule');}
function renderDrawer(kind){const custom={assets:assetsHTML,draw:drawHTML,branding:brandingHTML,access:accessHTML,voice:voiceHTML,schedule:O.libraryHTML};if(custom[kind]){$('#drawerTitle').textContent={assets:'Asset library',draw:'Drawing tools',branding:'Designer & logos',access:'Access points',voice:'SAMI voice & AI',schedule:'Materials schedule'}[kind];const box=$('#drawerContent');box.innerHTML=custom[kind]();box.onclick=e=>{const b=e.target.closest('[data-action]');if(b&&!ui.dragging)C.runAction(b.dataset.action,b);};C.bindDrawer(kind);return;}O.renderDrawer(kind);}
function bindDrawer(kind){if(!['project','assets','branding','access','voice','schedule'].includes(kind))O.bindDrawer(kind);
 if(kind==='assets'){C.bindAssetPaletteDrag();$('#assetSearch').oninput=e=>{ui.search=e.target.value;const pos=e.target.selectionStart;C.renderDrawer('assets');$('#assetSearch').focus();$('#assetSearch').setSelectionRange(pos,pos);};$$('[data-category]').forEach(d=>d.ontoggle=()=>{if(d.open)ui.category=d.dataset.category;});$('#studioLanes')?.addEventListener('change',()=>{S.project.route.lanes=+$('#studioLanes').value;C.saveSoon();});$('#libraryColour').onchange=()=>{S.project.assetColour=$('#libraryColour').value;C.saveSoon();};$('#repeatGap')?.addEventListener('change',()=>{S.project.assetGap=Math.max(0,+$('#repeatGap').value||0);C.saveSoon();});for(const id of ['customAssetLength','customAssetWidth'])$('#'+id)?.addEventListener('change',()=>{const a=getAsset();if(!a||a.dimensionLocked!==false)return;const l=+($('#customAssetLength')?.value||a.length),w=+($('#customAssetWidth')?.value||a.width);if(l>0&&w>0){a.length=Math.min(500,l);a.width=Math.min(500,w);const saved=S.project.customAssets.find(x=>x.kind===a.kind);if(saved){saved.length=a.length;saved.width=a.width;}C.saveSoon();}}); }
 if(kind==='project'){for(const id of ['siteAddress','what3words','siteRef','clientName','creator','drawingNo','revision','siteContact','sitePhone','siteEntrance','arrivalInstructions','driverNotes','siteNotes']){const el=$('#'+id);if(el)el.onchange=()=>{S.project.meta[id]=el.value;C.commit();};}$('#projectNameEdit').onchange=()=>{S.project.name=$('#projectNameEdit').value.trim()||'Untitled site';$('#projectName').value=S.project.name;C.commit();};$('#w3wApiKey').onchange=()=>C.setPref('sami.w3w.key',$('#w3wApiKey').value.trim());}
 if(kind==='branding'){for(const [id,key]of Object.entries({designerName:'creator',designerCompany:'designerCompany',designerEmail:'designerEmail',designerPhone:'designerPhone'}))$('#'+id).onchange=()=>{S.project.meta[key]=$('#'+id).value.trim();C.setPref('sami.designer',JSON.stringify(Object.fromEntries(['creator','designerCompany','designerEmail','designerPhone'].map(k=>[k,S.project.meta[k]||'']))));C.commit();};$$('[data-logo-export]').forEach(e=>e.onchange=()=>{S.project.logos.find(l=>l.id===e.dataset.logoExport).export=e.checked;C.commit();});}
 if(kind==='routeToSite'){$('#routeAccessPoint')?.addEventListener('change',e=>chooseAccessRoute(e.target.value));$('#routeEnd')?.addEventListener('change',()=>{delete S.project.hgv.accessPointId;});}
 if(kind==='voice'){ $('#voiceOutput').onchange=()=>{C.setPref('sami.voice.output',$('#voiceOutput').checked?'on':'off');C.updateVoiceButton();if(!$('#voiceOutput').checked)stopAudio();}; $('#voiceLiveFallback')?.addEventListener('change',()=>C.setPref('sami.voice.liveFallback',$('#voiceLiveFallback').checked?'on':'off')); }
}
function runAction(action,b){const [cmd,...args]=action.split(':'),arg=args.join(':');if(ui.dragging)return;try{
 if(action==='importShapePack'){$('#shapePackInput').click();return;}if(action==='exportShapePack'){exportShapePack();return;}if(action==='confirmAssetScale'){confirmAssetScale();return;}
 if(cmd==='pickAsset'){ui.asset=arg;ui.category=getAsset()?.category;ui.method=methodsFor(getAsset())[0];C.renderDrawer('assets');updateActiveTools();return;}
 if(cmd==='master'){ui.method=arg;activateMaster(arg);return;}if(action==='masterStart'){activateMaster();return;}
 if(action==='accessPoint'){C.startTool('accessPoint');return;}if(cmd==='accessEdit'){editAccessPoint(accessPoints().find(f=>f.id===arg));return;}if(action==='editAccess'){editAccessPoint(C.selectedFeature());return;}if(cmd==='accessRoute'){chooseAccessRoute(arg);return;}
 if(action==='uploadLogo'){$('#logoInput').click();return;}if(cmd==='pickLogo'){ui.asset='logo_'+arg;ui.method='place';C.closeDrawer();activateMaster();return;}if(cmd==='removeLogo'){S.project.logos=S.project.logos.filter(l=>l.id!==arg);C.commit();C.renderDrawer('branding');return;}
 if(action==='saveConnections'){for(const [id,key] of [['naturalVoiceUrl','sami.naturalVoice.url'],['connectedAiUrl','sami.ai.url']]){const value=$('#'+id).value.trim();if(value&&new URL(value).protocol!=='https:')throw Error('Use an HTTPS endpoint.');C.setPref(key,value);}C.toast('Connections saved.');return;}
 if(action==='toggleSelectedLock'){const fs=C.groupMembers();const locked=!fs[0]?.properties.locked;fs.forEach(f=>f.properties.locked=locked);C.commit();C.renderDrawer('selection');return;}
 if(['frontSelected','backSelected'].includes(action)){const fs=C.groupMembers(),ids=new Set(fs.map(f=>f.id)),other=S.project.features.filter(f=>!ids.has(f.id));S.project.features=action==='frontSelected'?[...other,...fs]:[...fs,...other];C.commit();return;}
 if(['hideItem','lockItem','raiseItem','lowerItem'].includes(cmd)){const f=S.project.features.find(f=>f.id===arg),members=C.groupMembers(f);if(cmd==='hideItem'){const value=!f.properties.hidden;members.forEach(x=>x.properties.hidden=value);}else if(cmd==='lockItem'){const value=!f.properties.locked;members.forEach(x=>x.properties.locked=value);}else{const ids=new Set(members.map(x=>x.id)),other=S.project.features.filter(x=>!ids.has(x.id));S.project.features=cmd==='raiseItem'?[...other,...members]:[...members,...other];}C.commit();C.renderDrawer('layers');return;}
 if(action==='rebuildLion'){rebuildLion();return;}
 if(action==='testVoice'){C.speakOptional("Hello, I'm SAMI. Your site planning workspace is ready.",{mode:'recorded',force:true});return;}
 if(action==='testSpeechPack'){C.speakOptional("Please build, make or generate a new object.",{mode:'auto',force:true});return;}
 if(action==='testNaturalVoice'){C.speakOptional("Hello, I'm SAMI. This is the live fallback voice. I should sound like the same speaker, with the same pace and tone.",{mode:'service',force:true});return;}
 O.runAction(action,b);
 }catch(e){C.toast(e.message);}}
function rebuildLion(){const f=C.selectedFeature(),product=f?.properties?.product||'lion',spec=PRODUCTS[product]||PRODUCTS.lion,guide=S.project.features.find(x=>x.properties.routeId===f?.properties?.routeId&&x.properties.guideHidden&&x.geometry.type==='LineString');if(!guide){C.toast('Only generated line runs can be rebuilt. Use the shared tools to draw a new area.');return;}C.showModal('Correct '+spec.name+' run width',C.choice('rebuildLanes','Finished run width',{'1':spec.width+' m · single','2':(spec.width*2)+' m · double'},String(S.project.route.lanes===2?2:1))+B('Rebuild run','confirmRebuild',true));$('#modalBody').onclick=e=>{if(!e.target.closest('[data-action="confirmRebuild"]'))return;const lanes=+$('#rebuildLanes').value,pts=copy(guide.geometry.coordinates),id=guide.properties.routeId;S.project.features=S.project.features.filter(x=>x.properties.routeId!==id);C.closeModal();C.addPanelRun(pts,{product,...spec,lanes});};}
function creatorState(){return ui.creator??={name:'My asset',length:6,width:2.5,parts:[],selected:-1};}
function creatorPush(){creatorHistory.push(copy(creatorState()));if(creatorHistory.length>60)creatorHistory.shift();}
function openCreator(){const c=creatorState(),el=$('#creatorWorkspace');el.hidden=false;el.innerHTML=`<div class="creator-tools"><div class="eyebrow">CREATE A SHAPE</div><h2>Build a shape</h2><p class="subtle">Combine simple parts, set real dimensions, then save to My shapes.</p><div class="compact-tools"><button data-create="rect">Rectangle</button><button data-create="ellipse">Ellipse</button><button data-create="line">Line</button><button data-create="triangle">Triangle</button><button data-create="duplicate">Duplicate part</button><button data-create="delete">Delete part</button></div><div class="row equal"><button data-create="truck">Truck template</button><button data-create="cabin">Cabin template</button></div><div class="row equal"><button data-create="import">Import stencil / CAD</button><button data-create="export">Export My shapes</button></div>${F('customName','Asset name',c.name)}<div class="row equal"><div>${F('customLength','Length (m)',c.length,'number','min="0.1" max="500" step="0.1"')}</div><div>${F('customWidth','Width (m)',c.width,'number','min="0.1" max="500" step="0.1"')}</div></div><div class="creator-props" id="creatorProps"></div><div class="row equal"><button data-create="undo">Undo part edit</button><button data-create="save" class="primary">Save to My shapes</button></div><button data-create="ask">Ask SAMI to help design</button><p class="subtle">Drag a part to move it. Use its properties to resize and colour it. A connected AI service can suggest a draft for review.</p></div><div class="creator-artboard"><div class="artboard-top"><strong>Top view</strong><span id="creatorSize"></span></div><svg id="creatorCanvas" viewBox="-10 -10 120 120" aria-label="Asset design canvas"><defs><pattern id="creatorGrid" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M5 0H0V5" fill="none" stroke="#e0e8e4" stroke-width=".2"/></pattern></defs><rect x="-10" y="-10" width="120" height="120" fill="url(#creatorGrid)"/><rect x="0" y="0" width="100" height="100" fill="#fff" stroke="#8eb3a6" stroke-width=".3"/><g id="creatorParts"></g></svg><div class="artboard-bottom">Real dimensions · reusable vector asset</div></div>`;
 el.onclick=e=>{const a=e.target.closest('[data-create]')?.dataset.create;if(a)creatorAction(a);};for(const [id,key]of [['customName','name'],['customLength','length'],['customWidth','width']])$('#'+id).onchange=()=>{creatorPush();c[key]=key==='name'?$('#'+id).value:Math.max(.1,Math.min(500,+$('#'+id).value||1));drawCreator();};bindCreatorDrag();drawCreator();}
function drawCreator(){const c=creatorState(),svg=$('#creatorCanvas');if(!svg)return;svg.style.aspectRatio=(c.length/c.width).toFixed(3);$('#creatorSize').textContent=c.length+' × '+c.width+' m';$('#creatorParts').innerHTML=c.parts.map((p,i)=>`<g data-part="${i}" class="${c.selected===i?'selected-part':''}">${D.svgParts([p],{styleFill:'#93baa9'})}</g>`).join('');const p=c.parts[c.selected],props=$('#creatorProps');props.innerHTML=p?'<div class="section-title">Selected part '+(c.selected+1)+'</div><div class="part-props">'+['x','y','w','h',...(p.type==='line'?['x2','y2']:[])].filter(k=>p[k]!=null).map(k=>F('part_'+k,k.toUpperCase(),p[k],'number','step="1" min="0" max="100"')).join('')+'<label>Colour<input type="color" id="partFill" value="'+colour(p.fill)+'"></label></div>':'<p class="subtle">Add or select a part.</p>';props.onchange=e=>{if(!p)return;creatorPush();const k=e.target.id.replace('part_','');if(e.target.id==='partFill')p.fill=e.target.value;else if(k in p)p[k]=Math.max(0,Math.min(100,+e.target.value||0));drawCreator();};}
function creatorAction(a){const c=creatorState(),selected=c.parts[c.selected];if(a==='import'){$('#shapePackInput').click();return;}if(a==='export'){exportShapePack();return;}if(a==='undo'){if(creatorHistory.length)ui.creator=creatorHistory.pop();openCreator();return;}if(a==='save'){if(!c.parts.length){C.toast('Add at least one part.');return;}if(!D.validParts(c.parts)){C.toast('The asset contains invalid shapes.');return;}const p={kind:'my_'+C.uid().replaceAll('-',''),name:String(c.name||'My asset').slice(0,100),length:+c.length,width:+c.width,category:'My shapes',symbolPartsJSON:JSON.stringify(c.parts),angle:0,dimensionLocked:false};S.project.customAssets.push(p);syncCatalogue();C.commit();C.toast('Saved to My shapes.');ui.asset=p.kind;ui.category='My shapes';C.setMode(S.project.area?'plan':'map');C.openDrawer('assets');return;}
 if(a==='ask'){document.body.classList.remove('ask-collapsed');$('#askInput').focus();$('#askInput').placeholder='Describe your asset, dimensions and parts…';return;}
 creatorPush();if(a==='truck'||a==='cabin'){c.parts=copy(D.parts(a==='truck'?'rigid':'cabin20'));c.name=a==='truck'?'My truck':'My cabin';c.length=a==='truck'?10.5:6.1;c.width=a==='truck'?2.55:2.44;openCreator();return;}
 if(a==='delete'&&selected){c.parts.splice(c.selected,1);c.selected=-1;}else if(a==='duplicate'&&selected){const p=copy(selected);if(p.x!=null)p.x=Math.min(75,p.x+5);if(p.y!=null)p.y=Math.min(75,p.y+5);if(p.points)p.points=p.points.map(([x,y])=>[Math.min(100,x+5),Math.min(100,y+5)]);c.parts.push(p);c.selected=c.parts.length-1;}else{const p={rect:D.P.rect(20,20,40,40),ellipse:D.P.ellipse(25,25,30,30),line:D.P.line(10,50,90,50),triangle:D.P.poly([[25,75],[50,25],[75,75]])}[a];if(p){c.parts.push(p);c.selected=c.parts.length-1;}}drawCreator();}
function bindCreatorDrag(){const canvas=$('#creatorCanvas');let drag=null;const coord=e=>{const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(canvas.getScreenCTM().inverse());return[p.x,p.y];};canvas.onpointerdown=e=>{const g=e.target.closest('[data-part]');if(!g)return;const c=creatorState();c.selected=+g.dataset.part;creatorPush();drag={id:e.pointerId,start:coord(e),part:copy(c.parts[c.selected])};canvas.setPointerCapture(e.pointerId);drawCreator();e.preventDefault();};canvas.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;const pos=coord(e),dx=pos[0]-drag.start[0],dy=pos[1]-drag.start[1],p=copy(drag.part);if(p.points)p.points=p.points.map(([x,y])=>[Math.max(0,Math.min(100,x+dx)),Math.max(0,Math.min(100,y+dy))]);else{p.x=Math.max(0,Math.min(100-(p.w||0),p.x+dx));p.y=Math.max(0,Math.min(100-(p.h||0),p.y+dy));if(p.x2!=null){p.x2=Math.max(0,Math.min(100,p.x2+dx));p.y2=Math.max(0,Math.min(100,p.y2+dy));}}creatorState().parts[creatorState().selected]=p;drawCreator();};const stop=()=>{drag=null;};canvas.onpointerup=stop;canvas.onpointercancel=stop;}
async function askAssetDesign(query){const endpoint=C.readPref('sami.ai.url')||window.SAMI_CONFIG?.aiEndpoint;if(!endpoint){const k=/truck|lorry|vehicle/i.test(query)?'rigid':/cabin|office|container/i.test(query)?'cabin20':/tent|marquee/i.test(query)?'marquee':null;if(k){creatorPush();const a=ASSETS[k];ui.creator={name:'My '+a.name,length:a.length,width:a.width,parts:copy(D.parts(k)),selected:-1};const match=query.match(/(\d+(?:\.\d+)?)\s*(?:m|metres?)?\s*(?:x|by|×)\s*(\d+(?:\.\d+)?)/i);if(match){ui.creator.length=Math.max(.1,Math.min(500,+match[1]));ui.creator.width=Math.max(.1,Math.min(500,+match[2]));}C.setMode('create');C.samiSay('I have opened an editable '+a.name+' template. Set the final dimensions, adjust its parts, then save it to My shapes.');}else{C.samiSay('The shape builder is ready. Add rectangles, ellipses, lines and triangles, or start from a truck or cabin. For an original AI design, connect your service in Voice & AI connections.');C.setMode('create');}return;}
 try{const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,mode:'assetDesign',units:'metres',schema:{name:'string',length:'number 0.1..500',width:'number 0.1..500',parts:'0..100 normalized rect/ellipse/line/poly primitives, max 120'},policy:'Return a draft JSON object {asset:{name,length,width,parts},answer}. No markup. Do not claim indicative dimensions are verified.'}),signal:AbortSignal.timeout(30000)}),data=await C.boundedJSON(res,150000),a=data.asset;if(!a||!D.validParts(a.parts)||!(a.length>.1&&a.length<=500&&a.width>.1&&a.width<=500))throw Error('The AI service returned an invalid asset draft.');creatorPush();ui.creator={name:String(a.name||'AI asset draft').slice(0,100),length:+a.length,width:+a.width,parts:a.parts,selected:-1};C.setMode('create');C.samiSay(data.answer||'Your draft is ready to review. Check the dimensions and save it to My shapes.');}catch(e){C.samiSay(e.message||'Asset design is unavailable. The shape builder remains available.');}}
async function handleCommand(q){if(S.mode==='create'||/\b(design|build)\b.*\b(my shape|custom asset|asset|truck|cabin|vehicle)\b/i.test(q)||/\bcreate\b.*\b(custom asset|my shape)\b/i.test(q)){await askAssetDesign(q);return;}if(/\b(access point|entrance|gate)\b/i.test(q)&&/\b(add|place|create)\b/i.test(q)){C.startTool('accessPoint');C.samiSay('Tap the entrance position, then add its name and address.');return;}window.SAMI_CONFIG.aiEndpoint=C.readPref('sami.ai.url')||window.SAMI_CONFIG.aiEndpoint;await O.handleCommand(q);}
function overpassFeatures(data,opts={}){if(!opts.powerAsService)return O.overpassFeatures(data,opts);const nodes=new Map((data.elements||[]).filter(x=>x.type==='node').map(n=>[n.id,n])),out=[],used=new Set(),bounds=ohlBounds(),capturedAt=new Date().toISOString(),supportKinds=new Set(['pole','tower','portal','terminal']);const meta=n=>({ref:n.tags?.ref||n.tags?.['ref:GB:power']||'',operator:n.tags?.operator||'',material:n.tags?.material||'',design:n.tags?.design||'',height:n.tags?.height||'',osmNodeId:n.id});const mappedKind=n=>n.tags?.power==='tower'?'pylon':n.tags?.power==='portal'?'portal':n.tags?.power==='terminal'?'terminal':'pole';for(const way of (data.elements||[]).filter(x=>x.type==='way'&&(['line','minor_line'].includes(x.tags?.power)||(x.tags?.power==='cable'&&x.tags?.location==='overhead')))){const coords=(way.nodes||[]).map(id=>nodes.get(id)).filter(Boolean).map(n=>[n.lon,n.lat]);if(coords.length<2)continue;const points=[],types={},metadata={};for(const id of way.nodes){const n=nodes.get(id);if(!supportKinds.has(n?.tags?.power))continue;const c=[n.lon,n.lat];if(bounds&&!G.inside(c,bounds))continue;used.add(id);points.push(c);const key=supportKey(c);metadata[key]={...meta(n),mappedKind:mappedKind(n)};}const geom=bounds?G.clipGeometry({type:'LineString',coordinates:coords},bounds):{type:'LineString',coordinates:coords};if(!geom)continue;out.push(C.feature('service',geom,{serviceType:'ohl',label:way.tags.name||way.tags.ref||'Overhead power line',voltage:way.tags.voltage||'',lineRef:way.tags.ref||'',operator:way.tags.operator||'',circuits:way.tags.circuits||'',cables:way.tags.cables||'',osmPower:way.tags.power||'',osmLocation:way.tags.location||'overhead',osmWayId:way.id,source:'OpenStreetMap power network',sourceId:'builtin:ohl-osm',capturedAt,verification:'Mapped reference · not surveyed',supportPointsJSON:JSON.stringify(points),supportTypesJSON:JSON.stringify(types),supportMetaJSON:JSON.stringify(metadata),includeLegend:true}));}
 for(const n of nodes.values()){if(used.has(n.id)||!supportKinds.has(n.tags?.power))continue;const c=[n.lon,n.lat];if(bounds&&!G.inside(c,bounds))continue;const key=supportKey(c);out.push(C.feature('service',{type:'Point',coordinates:c},{serviceType:'ohl',label:n.tags.ref||({'pole':'OHL pole','tower':'OHL tower','portal':'OHL portal','terminal':'OHL terminal'}[n.tags.power]||'OHL support'),source:'OpenStreetMap power network',sourceId:'builtin:ohl-osm',capturedAt,verification:'Mapped reference · not surveyed',supportNode:true,supportPointsJSON:JSON.stringify([c]),supportTypesJSON:'{}',supportMetaJSON:JSON.stringify({[key]:{...meta(n),mappedKind:mappedKind(n)}}),includeLegend:true}));}return out;}
async function refreshOhlSnapshot(){if(!S.project.area){C.openDrawer('area');return;}const bounds=ohlBounds(),generation=S.areaGeneration,project=S.project,previous=new Map();for(const f of project.features.filter(f=>f.properties.serviceType==='ohl')){const ms=readSupportMeta(f),ts=C.readSupportTypes(f);for(const [k,m]of Object.entries(ms))if(m.userEdited)previous.set(k,{meta:m,type:ts[k]});}C.toast('Finding mapped OHLs within the site + 0.5 mile intelligence buffer…');try{const bbox=[bounds[1],bounds[0],bounds[3],bounds[2]].join(','),query=`[out:json][timeout:35];(way["power"~"^(line|minor_line)$"](${bbox});way["power"="cable"]["location"="overhead"](${bbox});node["power"~"^(pole|tower|portal|terminal)$"](${bbox}););(._;>;);out body;`,data=await C.overpassQuery(query,16*1024*1024);if(project!==S.project||generation!==S.areaGeneration)return;const fs=C.overpassFeatures(data,{powerAsService:true});for(const f of fs){const ms=readSupportMeta(f),ts=C.readSupportTypes(f);for(const c of supports(f)){const k=supportKey(c),saved=previous.get(k);if(saved){ms[k]=saved.meta;ts[k]=saved.type;}}f.properties.supportMetaJSON=JSON.stringify(ms);f.properties.supportTypesJSON=JSON.stringify(ts);}await C.replaceSourceFeatures('builtin:ohl-osm',fs,'OHL intelligence snapshot');if(project!==S.project||generation!==S.areaGeneration)return;project.hiddenTypes=project.hiddenTypes.filter(t=>t!=='service');project.serviceVisibility.ohl=true;project.meta.ohlRefreshedAt=new Date().toISOString();project.meta.ohlCoverage='OSM mapped reference · site + 0.5 mile';const lineCount=fs.filter(f=>!f.properties.supportNode).length,supportCount=fs.filter(f=>f.properties.supportNode).length+fs.reduce((n,f)=>n+supports(f).length,0);C.commit();C.toast(`${lineCount} mapped OHL line records and ${supportCount} mapped support references saved. Verify before safety-critical use.`);}catch(e){C.toast('OHL refresh failed: '+e.message+'. Your saved records remain.');}}
function updateLaunchGate(){const splash=$('#splash');if(!splash)return;$('#splashStatus').textContent='Your site planning workspace is ready.';const start=$('#launchStartBtn');start.hidden=false;start.textContent='Open workspace';start.onclick=()=>{splash.remove();document.documentElement.classList.remove('browser-gated');};const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;$('#installGuide').hidden=false;$('#installGuide').innerHTML=ios?'<span>For a full-screen workspace: Safari → Share → Add to Home Screen.</span>':'<span>Install from your browser for a full-screen workspace, or open it here.</span>';document.documentElement.classList.remove('browser-gated');$('#installPwaBtn').hidden=true;}
