function commitSupport(id,key,kind,ref,voltage){const source=S.project.features.find(x=>x.id===id),position=supports(source).find(p=>supportKey(p)===key);if(!position)return;const uid='ohl-node-'+key,existing=S.project.features.find(x=>x.properties.ohlNodeKey===key),size=kind==='pole'||kind==='terminal'?.5:6,m={kind:kind==='pole'||kind==='terminal'?'pole':'tower',label:[kind==='pole'?'Pole':kind==='portal'?'Portal':kind==='terminal'?'OHL terminal':'Tower',ref,voltageLabel(voltage)].filter(Boolean).join(' · '),length:size,width:size,dimensionLocked:false,centerLng:position[0],centerLat:position[1],angle:0,ohlNodeKey:key,assetRef:ref,voltage,source:source.properties.source,verification:'User selected mapped record',includeLegend:true};if(existing){Object.assign(existing.properties,m);existing.geometry=G.rectangle(position,size,size,0);}else S.project.features.push(C.feature('asset',G.rectangle(position,size,size,0),m));for(const line of S.project.features.slice().filter(x=>x.properties.type==='service'&&x.properties.serviceType==='ohl'&&supports(x).some(p=>supportKey(p)===key))){if(!['LineString','MultiLineString'].includes(line.geometry.type))continue;const sourceKey=String(line.properties.osmWayId||line.id);if(S.project.features.some(x=>x.properties.ohlSourceKey===sourceKey))continue;const geometry=copy(line.geometry);S.project.features.push(C.feature('ohlCable',geometry,{label:line.properties.label||'Overhead cable',voltage:line.properties.voltage||voltage,lineRef:line.properties.lineRef||'',source:line.properties.source,ohlSourceKey:sourceKey,committed:true,includeLegend:true,styleColor:'#8c407a',styleWeight:1.2}));}}
const oldVisibleFeature=visibleFeature;
